sys_script.script:
(function executeRule(current, previous) {
    // Auto-generate Pass Number on Insert
    if (current.operation() == 'insert' && !current.getValue('pass_number')) {
        var lastGr = new GlideRecord('x_1877508_metro_0_metro_student_pass');
        lastGr.orderByDesc('sys_created_on');
        lastGr.setLimit(1);
        lastGr.query();

        var nextNum = 1;
        if (lastGr.next()) {
            var lastSpNum = lastGr.getValue('pass_number') || '';
            var numPart = parseInt(lastSpNum.replace('SP', ''), 10);
            if (!isNaN(numPart)) {
                nextNum = numPart + 1;
            }
        }

        var paddedNum = ('00000' + nextNum).slice(-5);
        current.setValue('pass_number', 'SP' + paddedNum);
    }

    // Pass Amount calculation
    var sourceStation = current.getValue('source_station');
    var destStation = current.getValue('destination_station');
    var passType = current.getValue('pass_type');

    if (!sourceStation || !destStation || !passType) {
        return;
    }

    // Find route distance
    var routeGr = new GlideRecord('x_1877508_metro_0_metro_routes');
    routeGr.addQuery('source_station', sourceStation);
    routeGr.addQuery('destination_station', destStation);
    routeGr.query();

    var distanceKm = 0;
    if (routeGr.next()) {
        distanceKm = parseFloat(routeGr.getValue('distance_km')) || 0;
    } else {
        // Try reverse route
        var reverseGr = new GlideRecord('x_1877508_metro_0_metro_routes');
        reverseGr.addQuery('source_station', destStation);
        reverseGr.addQuery('destination_station', sourceStation);
        reverseGr.query();
        if (reverseGr.next()) {
            distanceKm = parseFloat(reverseGr.getValue('distance_km')) || 0;
        }
    }

    if (distanceKm > 0) {
        var baseFare = distanceKm * 2;
        if (baseFare < 5) {
            baseFare = 5;
        }

        var rides = 0;
        var discountPercent = 0;

        if (passType == 'weekly') {
            rides = 10;
            discountPercent = 30;
        } else if (passType == 'monthly') {
            rides = 40;
            discountPercent = 40;
        }

        if (rides > 0) {
            var totalBeforeDiscount = baseFare * rides;
            var discountAmount = totalBeforeDiscount * (discountPercent / 100);
            var passAmount = totalBeforeDiscount - discountAmount;
            current.setValue('pass_amount', passAmount);
        }
    }
})(current, previous);
